{
  "candidate_edge_types": [
    {
      "name": "INVESTIGATES_FAILURE",
      "definition": "A diagnostic action that examines logs or output to determine the cause of an earlier observed execution failure.",
      "source_description": "An observed execution failure or error termination with an undetermined cause.",
      "target_description": "A subsequent diagnostic action that inspects output or logs to identify the cause of that failure."
    },
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action that attempts to resolve a previously identified execution failure.",
      "source_description": "A previously identified execution failure whose cause has been determined or suspected.",
      "target_description": "A subsequent agent action intended to resolve that failure."
    },
    {
      "name": "MONITORS_ASYNC_TASK",
      "definition": "A polling action that checks the progress or completion status of a long-running asynchronously launched process.",
      "source_description": "A long-running background process launched earlier whose completion status is unknown.",
      "target_description": "A subsequent polling action that inspects the process status or its log output."
    },
    {
      "name": "USES_SUCCESSFUL_RESULT_AS_PRECONDITION",
      "definition": "A subsequent action is initiated because an earlier prerequisite step completed successfully, satisfying the dependency it provides.",
      "source_description": "A successfully completed prerequisite step.",
      "target_description": "A subsequent action that depends on that prerequisite being satisfied."
    }
  ]
}

